const HM_CLIENT_KEYS=[...CLIENTS.slice(0,14),{...CLIENTS[18],gp:-55},{...CLIENTS[20],gp:-52}];
export const HEATMAP={
  products:['Масла ПКМ','Масла МКМ','Индустриальные масла','Пластичные смазки','СОЖ','Охлаждающие жидкости','Технические жидкости','Трансмиссионные масла'],
  clients:HM_CLIENT_KEYS.map(c=>[c.name,segEmoji[c.seg]]),
  /* Доля дистрибуции GP по категориям; индекс 5 (Охлаждающие) занижен ×0,6 — меш-гап у спец. жидкостей */
  A:(()=>{
    const mixDef=[['diamond',[0.28,0.22,0.14,0.10,0.05,0.06,0.09,0.06]],['platinum',[0.30,0.24,0.12,0.10,0.04,0.07,0.08,0.05]],['gold',[0.26,0.24,0.13,0.12,0.05,0.08,0.07,0.05]],['dist',[0.15,0.25,0.10,0.14,0.05,0.12,0.12,0.07]]];
    const getMix=c=>(mixDef.find(([k])=>k===c.seg)||mixDef[3])[1];
    const m=HM_CLIENT_KEYS.map(c=>{const gp=c.gp;const mix=getMix(c);return mix.map((w,i)=>+(gp*w).toFixed(2));});
    const rowsTotals=HM_CLIENT_KEYS.map(c=>c.gp);
    const mt=m[0].map((_,j)=>+sum(m.map(r=>r[j])).toFixed(2));
    return {cov:null, /* строится ниже в buildHeatmap */
            mrg:{m,mt,ct:rowsTotals.map(v=>+v.toFixed(2)),ctAll:+sum(rowsTotals).toFixed(1)}};
  })(),
  B:null,C:null, // заполняется ниже
  flatTable:{heads:['Клиент','Сегмент','Покр. ПКМ % (А/Б/В)','Покр. МКМ %','Покр. инд. %','Покр. смазки %','Покр. СОЖ %','Покр. ОЖ %','Покр. техж. %','Покр. трансм. %','Итого покр. %','Маржа ПКМ (А/Б/В)','Маржа МКМ','Маржа инд.','Маржа смазки','Маржа СОЖ','Маржа ОЖ','Маржа техж.','Маржа трансм.','Итого маржа'],rows:[]},
};
/* построение cov/mrg и дельт Б/В */
(function buildHeatmap(){
  const H=HEATMAP;
  const covBySeg={diamond:[100,100,100,100,100,98,100,98],platinum:[100,100,100,100,100,98,100,98],gold:[98,98,98,98,98,96,98,96],dist:[52,52,52,52,52,48,0,0]};
  const covBySegB={diamond:[110,110,108,108,105,108,110,108],platinum:[110,110,108,108,105,108,110,108],gold:[108,108,106,106,104,106,108,104],dist:[68,66,68,66,65,60,0,0]};
  const covBySegC={diamond:[100,100,100,100,100,100,100,100],platinum:[100,100,100,100,100,100,100,100],gold:[98,98,98,98,98,98,98,98],dist:[38,38,38,38,38,32,0,0]};
  const segKey=c=>['diamond','platinum','gold'].includes(c.seg)?c.seg:'dist';
  const r1=v=>Math.round(v*10)/10;
  const dl=v=>{if(!v)return 0;const r=r1(v);return Math.abs(r)<0.06?0:r;};
  const un=x=>x==null?0:(typeof x==='object'?x.v:x);
  H.A.cov={m:HM_CLIENT_KEYS.map(c=>covBySeg[segKey(c)].slice()),mt:[99,99,99,99,99,84,92,83],ct:HM_CLIENT_KEYS.map(c=>segKey(c)==='dist'?50:segKey(c)==='gold'?98:100),ctAll:94};
  const factor=0.10/0.23;
  H.B={cov:{m:HM_CLIENT_KEYS.map((c,i)=>H.A.cov.m[i].map((v,j)=>v==null?null:dl(covBySegB[segKey(c)][j]-v))),mt:H.A.cov.mt.map((v,j)=>dl([104,104,105,104,102,90,96,88][j]-v)),ct:HM_CLIENT_KEYS.map((c,i)=>dl((segKey(c)==='dist'?65:segKey(c)==='gold'?105:106)-H.A.cov.ct[i])),ctAll:11},
       mrg:{m:HM_CLIENT_KEYS.map((c,i)=>H.A.mrg.m[i].map((v,j)=>{if(v==null)return null;return dl(segKey(c)==='dist'?v*0.37:-v*0.014);}))}};
  H.B.mrg.mt=H.A.mrg.mt.map((v,j)=>dl(sum(H.B.mrg.m.map(r=>un(r[j])))));
  H.B.mrg.ct=H.A.mrg.ct.map((v,i)=>dl(sum(H.B.mrg.m[i].map(un))));
  H.B.mrg.ctAll=+r1(sum(H.B.mrg.ct)).toFixed(1);
  H.C={cov:{m:HM_CLIENT_KEYS.map((c,i)=>H.A.cov.m[i].map((v,j)=>{if(v==null)return null;const dist=segKey(c)==='dist';const d=dl(covBySegC[segKey(c)][j]-v);return dist?{v:d,good:1}:d;})),mt:H.A.cov.mt.map((v,j)=>dl([100,100,100,100,100,85,95,80][j]-v)),ct:HM_CLIENT_KEYS.map((c,i)=>{const dist=segKey(c)==='dist';const d=dl((dist?38:segKey(c)==='gold'?98:100)-H.A.cov.ct[i]);return dist?{v:d,good:1}:d;}),ctAll:{v:-3,good:1}},
       mrg:{m:HM_CLIENT_KEYS.map((c,i)=>H.A.mrg.m[i].map((v,j)=>{if(v==null)return null;const dist=segKey(c)==='dist';const d=dl(dist?Math.abs(v)*0.25:v*(0.04/0.23));return dist?{v:d,good:1}:d;}))}};
  H.C.mrg.mt=H.A.mrg.mt.map((v,j)=>dl(sum(H.C.mrg.m.map(r=>un(r[j])))));
  H.C.mrg.ct=H.A.mrg.ct.map((v,i)=>{const dist=segKey(HM_CLIENT_KEYS[i])==='dist';const s=+r1(sum(H.C.mrg.m[i].map(un))).toFixed(2);return dist?{v:s,good:1}:s;});
  H.C.mrg.ctAll={v:+r1(sum(H.C.mrg.ct.map(un))).toFixed(1),good:1};
  const lvl3=(a,b,c,digits)=>a==null?'—':F(a,digits)+'/'+F(a+un(b),digits)+'/'+F(a+un(c),digits);
  const rowBuild=(idx,segLbl)=>{
    const cells=[HM_CLIENT_KEYS[idx].name,segLbl];
    for(let j=0;j<8;j++)cells.push(H.A.cov.m[idx][j]==null?'—':lvl3(H.A.cov.m[idx][j],H.B.cov.m[idx][j],H.C.cov.m[idx][j],0));
    cells.push(lvl3(H.A.cov.ct[idx],H.B.cov.ct[idx],H.C.cov.ct[idx],0)+'%');
    for(let j=0;j<8;j++)cells.push(H.A.mrg.m[idx][j]==null?'—':lvl3(H.A.mrg.m[idx][j],H.B.mrg.m[idx][j],H.C.mrg.m[idx][j],1));
    cells.push(lvl3(H.A.mrg.ct[idx],H.B.mrg.ct[idx],H.C.mrg.ct[idx],1));
    return cells;
  };
  let total=['<b>Итого сегмент (16)</b>','—'];
  for(let j=0;j<8;j++)total.push('<b>'+lvl3(H.A.cov.mt[j],H.B.cov.mt[j],H.C.cov.mt[j],0)+'</b>');
  total.push('<b>'+lvl3(H.A.cov.ctAll,H.B.cov.ctAll,H.C.cov.ctAll,0)+'%</b>');
  for(let j=0;j<8;j++)total.push('<b>'+lvl3(H.A.mrg.mt[j],H.B.mrg.mt[j],H.C.mrg.mt[j],0)+'</b>');
  total.push('<b>'+lvl3(H.A.mrg.ctAll,H.B.mrg.ctAll,H.C.mrg.ctAll,0)+'</b>');
  H.flatTable={heads:H.flatTable.heads,rows:[rowBuild(0,'💎 Бриллиант'),rowBuild(4,'⬣ Платина'),rowBuild(10,'● Золото'),rowBuild(14,'🔴 Дилер (контроль)'),{cells:total,cls:'row-sum'}]};
})();

