/* ── Период-реактивные быстрые фильтры и генераторы для раздела «Планы» ── */
export const PLAN_PERIODS=[['all','Все 18 мес.'],['q4-2026','4 кв. 2026'],['y2027','2027 год'],['custom','Свой период']];
const PLAN_RANGE={all:[0,18],'q4-2026':[0,3],'y2027':[3,15]};
export function planRange(sel,cf,ct){
  if(sel==='custom'){const a=Math.max(0,Math.min(17,+cf||0));const b=Math.max(a+1,Math.min(18,(+ct||0)+1));return[a,b];}
  return PLAN_RANGE[sel]||PLAN_RANGE.all;
}
const sr=(arr,a,b)=>arr.slice(a,b).reduce((x,y)=>x+y,0);
const avg=(arr,a,b)=>{const s=arr.slice(a,b);return s.length?s.reduce((x,y)=>x+y,0)/s.length:0;};
const K=(label,value,sub)=>({label,value,sub});
const totalRow=cells=>({cells,cls:'row-total'});
export function planView(pl,a,b,qlabel){
  const L=MONTHS18,span=b-a;
  const impliedLabel=i=>{
    if(span===3&&a===0&&(qlabel==='q4-2026'||qlabel==null))return '4 кв. 2026 в среднем';
    if(span===12&&a===3&&qlabel==='y2027')return L[a]+' – '+L[b-1]+' в среднем';
    return L[a]+'–'+L[b-1]+' в среднем';
  };
  if(pl==='sales'){
    const vol=sr(sales,a,b),rev=sr(revenue,a,b),gm=rev*0.23;
    return{kpis:[K('План продаж',F(vol)+' т',F(rev,1)+' млн руб.'),K('Средняя цена',F(vol?rev/vol*1e6:0)+' руб/т','План 141 500 руб/т'),K('Валовая маржа',F(gm,1)+' млн','23,0% от выручки'),K('Период',span+' мес.',L[a]+' – '+L[b-1])],
      table:{heads:['Месяц','План объёма (т)','План выручки (млн руб.)','Средняя цена (руб/т)','Валовая маржа (млн руб.)','Маржа %'],
        rows:[...L.slice(a,b).map((m,i)=>[m,F(sales[a+i]),F(revenue[a+i],1),F(141500),F(revenue[a+i]*0.23,1),'23%']),totalRow(['<b>Итого</b>','<b>'+F(vol)+'</b>','<b>'+F(rev,1)+'</b>','<b>'+F(vol?rev/vol*1e6:0)+'</b>','<b>'+F(gm,1)+'</b>','<b>23%</b>'])]},
      detail:PLANS.sales.build(a,b)};
  }
  if(pl==='production'){
    const prod=sr(production,a,b),vol=sr(sales,a,b),load=avg(capacity,a,b);
    return{kpis:[K('План производства',F(prod)+' т','загрузка '+F(load,0)+'%'),K('Δ к продажам','+'+F(prod-vol)+' т','восстановление запаса'),K('Средняя загрузка',F(load,0)+'%','цель 90%'),K('Период',span+' мес.',L[a]+' – '+L[b-1])],
      table:{heads:['Месяц','Производство (т)','Загрузка %','Продажи (т)','Δ к продажам (т)'],
        rows:[...L.slice(a,b).map((m,i)=>[m,F(production[a+i]),capacity[a+i]+'%',F(sales[a+i]),(production[a+i]-sales[a+i]>=0?'+':'')+F(production[a+i]-sales[a+i])]),totalRow(['<b>Итого</b>','<b>'+F(prod)+'</b>','<b>'+F(load,0)+'%</b>','<b>'+F(vol)+'</b>','<b>+'+F(prod-vol)+'</b>'])]},
      detail:PLANS.production.build(a,b)};
  }
  if(pl==='movements'){
    const au=sr(movementAuto,a,b),ra=sr(movementRail,a,b),tot=au+ra;
    return{kpis:[K('План перемещений',F(tot)+' т',F((au+ra)*.0032,0)+' млн руб.'),K('Авто',F(au)+' т',F(tot?au/tot*100:0,0)+'%'),K('ЖД',F(ra)+' т',F(tot?ra/tot*100:0,0)+'%'),K('Период',span+' мес.',L[a]+' – '+L[b-1])],
      table:{heads:['Месяц','Авто (т)','ЖД (т)','Итого (т)','Стоимость (млн)'],
        rows:[...L.slice(a,b).map((m,i)=>[m,F(movementAuto[a+i]),F(movementRail[a+i]),F(movementAuto[a+i]+movementRail[a+i]),F((movementAuto[a+i]+movementRail[a+i])*.0032,1)]),totalRow(['<b>Итого</b>','<b>'+F(au)+'</b>','<b>'+F(ra)+'</b>','<b>'+F(tot)+'</b>','<b>'+F(tot*.0032,1)+'</b>'])]},
      detail:PLANS.movements.build(a,b)};
  }
  if(pl==='purchases'){
    const g3=sr(purchG3,a,b),ba=sr(purchBase,a,b),ad=sr(purchAdd,a,b);
    const tot=g3+ba+ad;
    return{kpis:[K('План закупок',F(tot,0)+' млн','сырьё и присадки'),K('VHVI/базовые масла',F(g3+ba,0)+' млн',F(tot?(g3+ba)/tot*100:0,0)+'% — риск VHVI-4'),K('Присадки',F(ad,0)+' млн',F(tot?ad/tot*100:0,0)+'%'),K('Период',span+' мес.',L[a]+' – '+L[b-1])],
      table:{heads:['Месяц','VHVI/базовые (млн)','ННОС/спец (млн)','Присадки (млн)','Итого (млн)'],
        rows:[...L.slice(a,b).map((m,i)=>{
          const t=purchG3[a+i]+purchBase[a+i]+purchAdd[a+i];
          return [m,F(purchG3[a+i],0),F(purchBase[a+i],0),F(purchAdd[a+i],0),F(t,0)];}),
          totalRow(['<b>Итого</b>','<b>'+F(g3,0)+'</b>','<b>'+F(ba,0)+'</b>','<b>'+F(ad,0)+'</b>','<b>'+F(tot,0)+'</b>'])]},
      detail:PLANS.purchases.build(a,b)};
  }
  if(pl==='inventory'){
    const mean=avg(inv,a,b),md=avg(invDays,a,b),meanCost=avg(invCost,a,b);
    return{kpis:[K('Средний запас',F(mean,0)+' т',F(md,1)+' дней покрытия'),K('Стоимость запасов',F(meanCost,0)+' млн','~+20% к целевой '+F(avg(invCostTarget,a,b),0)+' млн'),K('Δ к цели','+'+F(avg(invPct.slice(a,b),0,span),0)+'%','коридор +15…+25%'),K('Период',span+' мес.',L[a]+' – '+L[b-1])],
      table:{heads:['Месяц','План запасов (т)','Дней покрытия','Стоимость (млн)','Цель (т)','Δ к цели','Статус'],
        rows:[...L.slice(a,b).map((m,i)=>{const v=inv[a+i],pc=invPct[a+i];return[m,F(v),F(invDays[a+i],1),F(invCost[a+i]),F(invTarget[a+i]),'+'+F(v-invTarget[a+i])+' / +'+pc+'%',pc>=15&&pc<=25?'🟢 В коридоре +20%':'🟠 Вне коридора'];}),
          totalRow(['<b>'+impliedLabel()+'</b>','<b>'+F(mean,0)+'</b>','<b>'+F(md,1)+'</b>','<b>'+F(meanCost,0)+'</b>','<b>'+F(avg(invTarget,a,b),0)+'</b>','<b>+'+F(avg(invPct.slice(a,b),0,span),0)+'%</b>','—'])]},
      detail:PLANS.inventory.build(a,b)};
  }
  if(pl==='cost'){
    const items=costItems.map(([n,w])=>[n,sr(revenue.map(x=>+ (x*w).toFixed(1)),a,b)]);
    const tot=sr(revenue.map(x=>+(x*.769).toFixed(1)),a,b),rev=sr(revenue,a,b);
    return{kpis:[K('Себестоимость',F(tot,0)+' млн',F(rev?tot/rev*100:0,1)+'% выручки'),K('Сырьё',F(items[0][1],0)+' млн','46,2% выручки'),K('Производство + логистика',F(items[1][1]+items[2][1],0)+' млн','19,2%'),K('Период',span+' мес.',L[a]+' – '+L[b-1])],
      table:{heads:['Месяц',...costItems.map(x=>x[0]),'Итого','% выручки'],
        rows:[...L.slice(a,b).map((m,i)=>{
          const rs=costItems.map(([n,w])=>F(revenue[a+i]*w,1));
          return [m,...rs,F(revenue[a+i]*.769,1),'77,0%'];}),
          totalRow(['<b>Итого</b>',...items.map(([n,v])=>'<b>'+F(v,1)+'</b>'),'<b>'+F(tot,1)+'</b>','<b>77,0%</b>'])]},
      detail:PLANS.cost.build(a,b)};
  }
  // revenue
  const rev=sr(revenue,a,b),gm=rev*0.23;
  return{kpis:[K('План выручки',F(rev,1)+' млн','валовая прибыль '+F(gm,1)+' млн'),K('Средняя цена',F(141500)+' руб/т','стабильно на горизонте'),K('Маржа','23,0%','ПКМ/MTO-премиум до 26%'),K('Период',span+' мес.',L[a]+' – '+L[b-1])],
    table:{heads:['Месяц','Выручка (млн руб.)','Валовая прибыль (млн руб.)','Объём (т)','Средняя цена (руб/т)'],
      rows:[...L.slice(a,b).map((m,i)=>[m,F(revenue[a+i],1),F(revenue[a+i]*.23,1),F(sales[a+i]),F(141500)]),totalRow(['<b>Итого</b>','<b>'+F(rev,1)+'</b>','<b>'+F(gm,1)+'</b>','<b>'+F(sr(sales,a,b))+'</b>','<b>141 500</b>'])]},
    detail:PLANS.revenue.build(a,b)};
}

